const stdout = $input.item.json.stdout || '';

// Parse config and processed jobs from combined output
const parts = stdout.split('---PROCESSED---');
const configPart = (parts[0] || '').replace('---CONFIG---', '').trim();
const processedPart = parts[1] || '';

let config = {};
try {
  config = JSON.parse(configPart);
} catch(e) {
  console.log('Config parse error:', e.message);
}

// Parse processed job links (one URL per line, skip comments)
const processedLinks = processedPart
  .split('\n')
  .map(line => line.trim())
  .filter(line => line && !line.startsWith('#') && line.startsWith('http'));

console.log(`Loaded ${processedLinks.length} previously processed job links`);

const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);

return [{
  json: {
    jobTitles: config.job_titles || ['Engineering Manager'],
    location: config.location || 'London, UK',
    timeRange: config.time_range || '48h',
    excludeInTitle: config.exclude_in_title || [],
    excludeInDescription: config.exclude_in_description || [],
    flagForReview: config.flag_for_review || [],
    mustHaveKeywords: config.must_have || [],
    minScore: config.min_score || 7,
    maxJobs: config.max_jobs_per_title || 20,
    maxJobsTotal: config.max_jobs_total || 999,
    debugMode: config.debug_mode || false,
    skipCoverLetters: config.skip_cover_letters || false,
    ollamaModel: config.ollama_model || 'qwen2.5:latest',
    ollamaUrl: config.ollama_url || 'http://host.docker.internal:11434',
    runTimestamp: timestamp,
    jobsProcessed: 0,
    processedLinks: processedLinks,
    outputFileMatches: `/data/n8n_linkedin/output/matches_${timestamp}.json`,
    outputFileRejected: `/data/n8n_linkedin/output/rejected_${timestamp}.json`,
    metadata: {
      source: 'LinkedIn (via Python scraper)',
      aiProvider: 'Ollama (local)',
      aiModel: config.ollama_model || 'qwen2.5:latest',
      candidateName: 'Joao Lourenco',
      runDate: now.toISOString(),
      configVersion: '4.2-dedup'
    }
  }
}];

// Process ALL jobs for this search title in one Code node
// This avoids n8n's splitInBatches loop issues
// v4.2: Added deduplication - skip already processed jobs

const jobsText = $input.item.json.stdout || '[]';
let jobs = [];

try {
  jobs = JSON.parse(jobsText);
} catch(e) {
  console.log('JSON parse error:', e.message);
  jobs = [];
}

const config = $('Parse Config').item.json;
const searchTitle = $('Loop Job Titles').item.json.jobTitles;

// Load already processed job links
let processedLinks = new Set();
try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'file:///data/n8n_linkedin/python/processed_jobs.txt',
    returnFullResponse: false
  });
} catch(e) {
  // File might not exist or be accessible via HTTP, try reading differently
}

// For now, we'll track in the output and update the file via shell command
// The processedLinks will be passed through the workflow
const previouslyProcessed = config.processedLinks || [];
processedLinks = new Set(previouslyProcessed);

// Filter out already processed jobs
const originalCount = jobs.length;
jobs = jobs.filter(job => {
  const link = job.job_link || '';
  if (!link) return true; // Keep jobs without links
  if (processedLinks.has(link)) {
    console.log(`SKIP (already processed): ${job.title} at ${job.company}`);
    return false;
  }
  return true;
});
const skippedCount = originalCount - jobs.length;
if (skippedCount > 0) {
  console.log(`Skipped ${skippedCount} already-processed jobs`);
}

// Check if we've already hit the total job limit
const maxTotal = config.maxJobsTotal || 999;
let processedSoFar = config.jobsProcessed || 0;

if (processedSoFar >= maxTotal) {
  console.log(`LIMIT REACHED: Already processed ${processedSoFar}/${maxTotal} jobs. Skipping ${searchTitle}`);
  return [{ json: { matches: [], rejected: [], searchTitle, config, limitReached: true, newProcessedLinks: [] } }];
}

if (!Array.isArray(jobs) || jobs.length === 0) {
  console.log(`No new jobs found for: ${searchTitle}`);
  return [{ json: { matches: [], rejected: [], searchTitle, config, newProcessedLinks: [] } }];
}

// Limit jobs to process based on remaining quota
const remaining = maxTotal - processedSoFar;
if (jobs.length > remaining) {
  console.log(`DEBUG MODE: Limiting from ${jobs.length} to ${remaining} jobs (max_jobs_total: ${maxTotal})`);
  jobs = jobs.slice(0, remaining);
}

console.log(`Processing ${jobs.length} NEW jobs for: ${searchTitle} (${processedSoFar} already done, max: ${maxTotal})`);

// Track newly processed links to save later
const newProcessedLinks = [];

const matches = [];
const rejected = [];

// Three-tier filtering (case-insensitive)
const excludeInTitle = (config.excludeInTitle || []).map(k => k.toLowerCase());
const excludeInDescription = (config.excludeInDescription || []).map(k => k.toLowerCase());
const flagForReview = (config.flagForReview || []).map(k => k.toLowerCase());

// System prompt for job analysis
const systemPrompt = `You are a job matching assistant. Analyze job postings and return JSON assessments.

CANDIDATE PROFILE:
Name: Joao Lourenco
Role: Engineering Manager
Location: London, UK
Experience: 14+ years software quality, 8+ years leading teams
Team Size: Managed 16 people including 2 Engineering Managers
Scaling: Grew teams from 4 to 16 engineers with 100% UK retention
Domains: Safety-critical (automotive, aerospace, defence), static analysis
Compliance: ISO 9001, ISO 27001, DO-178B
Technical: Test automation, CI/CD, Python, TypeScript, Jenkins, AWS
Achievements: Reduced 4-month testing to 2-day automated, 90% defect reduction

REJECT IF:
- Hands-on IC coding role (not management)
- Hardware/embedded/electrical engineering
- Mechanical/civil/construction
- Junior or mid-level positions
- C-suite requiring 20+ years
- Non-software industries

SCORING:
9-10: Perfect match (EM, safety-critical, team scaling)
7-8: Strong match (EM software, good seniority)
5-6: Partial match (some alignment)
1-4: Poor match

Return ONLY valid JSON, no markdown.`;

// Process each job sequentially
for (let i = 0; i < jobs.length; i++) {
  const jobData = jobs[i];
  const job = {
    title: jobData.title || 'Unknown Title',
    company: jobData.company || 'Unknown Company',
    location: jobData.location || '',
    job_link: jobData.job_link || '',
    posted_date: jobData.posted_date || '',
    description: jobData.description || ''
  };

  console.log(`[${i+1}/${jobs.length}] Checking: ${job.title} at ${job.company}`);

  // THREE-TIER PRE-FILTER
  const titleLower = job.title.toLowerCase();
  const descLower = job.description.toLowerCase();
  const allTextLower = `${titleLower} ${job.company.toLowerCase()} ${descLower}`;

  // TIER 1: Hard reject if keyword in TITLE
  let titleRejection = null;
  for (const keyword of excludeInTitle) {
    if (titleLower.includes(keyword)) {
      titleRejection = `Title contains: "${keyword}"`;
      break;
    }
  }

  if (titleRejection) {
    console.log(`  -> AUTO-REJECTED (title): ${titleRejection}`);
    rejected.push({
      job: job,
      analysis: {
        relevant: false,
        rejection_reason: titleRejection,
        score: 0,
        company_size: 'Unknown',
        company_industry: 'Unknown',
        seniority_level: 'Unknown'
      },
      metadata: {
        ...config.metadata,
        searchTitle: searchTitle,
        processedAt: new Date().toISOString(),
        status: 'auto-rejected-title'
      }
    });
    continue;
  }

  // TIER 2: Hard reject if specific industry keywords in DESCRIPTION
  let descRejection = null;
  for (const keyword of excludeInDescription) {
    if (descLower.includes(keyword)) {
      descRejection = `Description contains: "${keyword}"`;
      break;
    }
  }

  if (descRejection) {
    console.log(`  -> AUTO-REJECTED (description): ${descRejection}`);
    rejected.push({
      job: job,
      analysis: {
        relevant: false,
        rejection_reason: descRejection,
        score: 0,
        company_size: 'Unknown',
        company_industry: 'Unknown',
        seniority_level: 'Unknown'
      },
      metadata: {
        ...config.metadata,
        searchTitle: searchTitle,
        processedAt: new Date().toISOString(),
        status: 'auto-rejected-description'
      }
    });
    continue;
  }

  // TIER 3: Flag for review if soft keywords found anywhere
  let reviewFlags = [];
  for (const keyword of flagForReview) {
    if (allTextLower.includes(keyword)) {
      reviewFlags.push(keyword);
    }
  }
  const needsReview = reviewFlags.length > 0;
  if (needsReview) {
    console.log(`  -> FLAGGED for review: ${reviewFlags.join(', ')}`);
  }

  console.log(`  -> Passed pre-filters, calling AI...`);

  // Clean description
  const cleanDesc = (job.description || '')
    .substring(0, 2000)
    .replace(/[\x00-\x1F\x7F]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim() || 'No description available';

  const userPrompt = `Analyze this job:\n\nTitle: ${job.title}\nCompany: ${job.company}\nLocation: ${job.location}\n\nDescription:\n${cleanDesc}\n\n---\nReturn JSON with these fields:\n{\n  "relevant": true/false,\n  "rejection_reason": null or string,\n  "score": 1-10,\n  "company_size": string,\n  "company_industry": string,\n  "company_about": string,\n  "role_summary": string,\n  "match_reasons": [array],\n  "concerns": [array],\n  "seniority_level": string\n}`;

  let analysis = {
    relevant: false,
    rejection_reason: 'Failed to analyze',
    score: 0,
    company_size: 'Unknown',
    company_industry: 'Unknown',
    company_about: '',
    role_summary: '',
    match_reasons: [],
    concerns: [],
    seniority_level: 'Unknown'
  };

  try {
    // Call Ollama API
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: `${config.ollamaUrl}/api/chat`,
      body: {
        model: config.ollamaModel,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt }
        ],
        stream: false,
        options: { temperature: 0.3 }
      },
      json: true,
      timeout: 120000
    });

    // Parse response
    let responseText = response.message?.content || response.response || '';
    responseText = responseText.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();

    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      analysis = JSON.parse(jsonMatch[0]);
    }
  } catch(e) {
    console.log(`Error analyzing job: ${e.message}`);
    analysis.rejection_reason = 'Ollama error: ' + e.message;
  }

  analysis.score = parseInt(analysis.score) || 0;

  console.log(`  -> Score: ${analysis.score}, Relevant: ${analysis.relevant}`);

  // Check if matches criteria
  if (analysis.relevant === true && analysis.score >= config.minScore) {
    // Generate cover letter for matches (unless skipped for debugging)
    let coverLetter = '';
    if (config.skipCoverLetters) {
      coverLetter = '[Cover letter skipped - debug mode]';
      console.log(`  -> Skipping cover letter (debug mode)`);
    } else {
      try {
        const coverResponse = await this.helpers.httpRequest({
          method: 'POST',
          url: `${config.ollamaUrl}/api/chat`,
          body: {
            model: config.ollamaModel,
            messages: [
              { role: 'system', content: 'Write a professional cover letter. Be concise (300-400 words). No placeholder brackets. Ready to send.' },
              { role: 'user', content: `Write a cover letter for Joao Lourenco applying to:\n\nPosition: ${job.title}\nCompany: ${job.company}\n\nRole Summary: ${analysis.role_summary}\n\nWhy this matches:\n${(analysis.match_reasons || []).join('\n')}\n\nCandidate highlights:\n- Engineering Manager, 14+ years experience\n- Scaled teams 4 to 16 engineers\n- Safety-critical: automotive, aerospace, defence\n- 90% defect reduction\n\nAddress to 'Hiring Manager', sign as 'Joao Lourenco'.` }
            ],
            stream: false,
            options: { temperature: 0.7 }
          },
          json: true,
          timeout: 120000
        });
        coverLetter = coverResponse.message?.content || coverResponse.response || '';
      } catch(e) {
        coverLetter = 'Error generating cover letter: ' + e.message;
      }
    }

    const matchEntry = {
      job: job,
      analysis: analysis,
      cover_letter: coverLetter.trim(),
      needsReview: needsReview,
      reviewFlags: reviewFlags,
      metadata: {
        ...config.metadata,
        searchTitle: searchTitle,
        processedAt: new Date().toISOString(),
        status: needsReview ? 'matched-needs-review' : 'matched'
      }
    };
    matches.push(matchEntry);
    console.log(`  -> MATCHED!${needsReview ? ' (NEEDS REVIEW)' : ''}`);
  } else {
    // Add to rejected
    rejected.push({
      job: job,
      analysis: {
        relevant: analysis.relevant || false,
        rejection_reason: analysis.rejection_reason || `Score ${analysis.score} below minimum ${config.minScore}`,
        score: analysis.score,
        company_size: analysis.company_size,
        company_industry: analysis.company_industry,
        seniority_level: analysis.seniority_level
      },
      needsReview: needsReview,
      reviewFlags: reviewFlags,
      metadata: {
        ...config.metadata,
        searchTitle: searchTitle,
        processedAt: new Date().toISOString(),
        status: needsReview ? 'rejected-needs-review' : 'rejected'
      }
    });
  }
}

console.log(`Done! Matches: ${matches.length}, Rejected: ${rejected.length}`);

// Collect all job links that were processed
for (const m of matches) {
  if (m.job?.job_link) newProcessedLinks.push(m.job.job_link);
}
for (const r of rejected) {
  if (r.job?.job_link) newProcessedLinks.push(r.job.job_link);
}

// Update processed count for next iteration
const updatedConfig = { ...config, jobsProcessed: processedSoFar + jobs.length };

console.log(`Total processed so far: ${updatedConfig.jobsProcessed}/${maxTotal}`);
console.log(`New job links to save: ${newProcessedLinks.length}`);

// Return results - will be saved by next node
return [{
  json: {
    matches: matches,
    rejected: rejected,
    searchTitle: searchTitle,
    config: updatedConfig,
    newProcessedLinks: newProcessedLinks,
    stats: {
      total: jobs.length,
      matched: matches.length,
      rejected: rejected.length,
      totalProcessed: updatedConfig.jobsProcessed,
      maxTotal: maxTotal,
      skipped: skippedCount || 0
    }
  }
}];

const data = $input.item.json;
const config = data.config;
const matches = data.matches || [];
const rejected = data.rejected || [];

// Write each result individually as base64 chunks
const results = [];

// Add matches one by one
for (const match of matches) {
  // Flatten for Excel row
  const excelRow = {
    status: match.needsReview ? 'REVIEW' : 'MATCH',
    needs_review: match.needsReview ? 'YES' : '',
    review_flags: (match.reviewFlags || []).join('; '),
    title: match.job?.title || '',
    company: match.job?.company || '',
    location: match.job?.location || '',
    job_link: match.job?.job_link || '',
    posted_date: match.job?.posted_date || '',
    score: match.analysis?.score || 0,
    seniority: match.analysis?.seniority_level || '',
    industry: match.analysis?.company_industry || '',
    company_size: match.analysis?.company_size || '',
    role_summary: match.analysis?.role_summary || '',
    match_reasons: (match.analysis?.match_reasons || []).join('; '),
    concerns: (match.analysis?.concerns || []).join('; '),
    cover_letter: match.cover_letter || '',
    processed_at: match.metadata?.processedAt || ''
  };

  results.push({
    type: 'match',
    data: Buffer.from(JSON.stringify(match)).toString('base64'),
    excelRow: Buffer.from(JSON.stringify(excelRow)).toString('base64'),
    file: config.outputFileMatches,
    excelFile: config.outputFileMatches.replace('.json', '.xlsx'),
    jobLink: match.job?.job_link || ''
  });
}

// Add rejected one by one  
for (const rej of rejected) {
  const excelRow = {
    status: 'REJECTED',
    needs_review: rej.needsReview ? 'YES' : '',
    review_flags: (rej.reviewFlags || []).join('; '),
    title: rej.job?.title || '',
    company: rej.job?.company || '',
    location: rej.job?.location || '',
    job_link: rej.job?.job_link || '',
    posted_date: rej.job?.posted_date || '',
    score: rej.analysis?.score || 0,
    seniority: rej.analysis?.seniority_level || '',
    industry: rej.analysis?.company_industry || '',
    company_size: rej.analysis?.company_size || '',
    rejection_reason: rej.analysis?.rejection_reason || '',
    match_reasons: '',
    concerns: '',
    cover_letter: '',
    processed_at: rej.metadata?.processedAt || ''
  };

  results.push({
    type: 'rejected',
    data: Buffer.from(JSON.stringify(rej)).toString('base64'),
    excelRow: Buffer.from(JSON.stringify(excelRow)).toString('base64'),
    file: config.outputFileRejected,
    excelFile: config.outputFileRejected.replace('.json', '.xlsx'),
    jobLink: rej.job?.job_link || ''
  });
}

// Return array of items to process
if (results.length === 0) {
  return [{ json: { skip: true, stats: data.stats } }];
}

return results.map(r => ({ json: r }));
